SELECT gen_random_uuid()::text, 'formula', '$h$', 'Free-Fall Equations', '$v = gt,\qquad h = \tfrac12 gt^2,\qquad v = \sqrt{2gh}$', '$\text{m}$', 'Motion of a body dropped from rest, air resistance ignored.', '[{"symbol":"$g$","meaning":"acceleration due to gravity","unit":"$\\text{m/s}^2$"},{"symbol":"$t$","meaning":"time from rest","unit":"$\\text{s}$"},{"symbol":"$h$","meaning":"distance fallen","unit":"$\\text{m}$"}]'::jsonb, 'Mass doesn''t appear: everything falls at the same rate in a vacuum.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Physics for Engineers' AND t."subject" = 'ESAS' AND s."normKey" = 'kinematics' AND s."active"), NULL, false, 'PENDING', now(), now()
